{"version":3,"sources":["../../src/health/prisma.health.ts"],"sourcesContent":["import {\n  HealthCheckError,\n  HealthIndicator,\n  type HealthIndicatorResult,\n} from '@nestjs/terminus';\nimport { PrismaService } from '../prisma/prisma.service';\n\nexport class PrismaHealthIndicator extends HealthIndicator {\n  constructor(private readonly prisma: PrismaService) {\n    super();\n  }\n\n  async isHealthy(key: string): Promise<HealthIndicatorResult> {\n    try {\n      await this.prisma.$queryRaw`SELECT 1`;\n      return this.getStatus(key, true);\n    } catch (error) {\n      throw new HealthCheckError('Prisma check failed', error);\n    }\n  }\n}\n"],"names":["PrismaHealthIndicator","HealthIndicator","isHealthy","key","prisma","$queryRaw","getStatus","error","HealthCheckError"],"mappings":";;;;+BAOaA;;;eAAAA;;;0BAHN;AAGA,IAAA,AAAMA,wBAAN,MAAMA,8BAA8BC,yBAAe;IAKxD,MAAMC,UAAUC,GAAW,EAAkC;QAC3D,IAAI;YACF,MAAM,IAAI,CAACC,MAAM,CAACC,SAAS,CAAC,QAAQ,CAAC;YACrC,OAAO,IAAI,CAACC,SAAS,CAACH,KAAK;QAC7B,EAAE,OAAOI,OAAO;YACd,MAAM,IAAIC,0BAAgB,CAAC,uBAAuBD;QACpD;IACF;IAXA,YAAY,AAAiBH,MAAqB,CAAE;QAClD,KAAK,SADsBA,SAAAA;IAE7B;AAUF"}
